MagickBooleanType ReadPSDPixelData(Image *image, size_t channels, size_t row,
                                    ssize_t type, const unsigned char *pixels,
                                    ExceptionInfo *exception) {
  register PixelIntensity *magick_restrict q;
  register ssize_t x;
  ssize_t
    depth;

  depth = (ssize_t) (image->depth);
  if (image->storage_class == PseudoClass)
    depth = 8;
  if (image->alpha_trait != UndefinedPixelTrait)
    channels++;
  q = (PixelIntensity *) GetPixelCacheViewRow(image, row);
  if (q == (PixelIntensity *) NULL)
    return MagickFalse;
  for (x=0; x < (ssize_t) image->columns; x++) {
    register ssize_t
      i;

    switch (type) {
      case 0: {
        for (i=0; i < (ssize_t) channels; i++) {
          switch (i) {
            case 0:
              q->red = ScaleShortToQuantum((unsigned short) *pixels);
              break;
            case 1:
              q->green = ScaleShortToQuantum((unsigned short) *pixels);
              break;
            case 2:
              q->blue = ScaleShortToQuantum((unsigned short) *pixels);
              break;
            case 3:
              q->alpha = ScaleShortToQuantum((unsigned short) *pixels);
              break;
          }
          pixels++;
        }
        break;
      }
      case 1: {
        for (i=0; i < (ssize_t) channels; i++) {
          switch (i) {
            case 0:
              q->red = ScaleLongToQuantum((unsigned int) *pixels);
              break;
            case 1:
              q->green = ScaleLongToQuantum((unsigned int) *pixels);
              break;
            case 2:
              q->blue = ScaleLongToQuantum((unsigned int) *pixels);
              break;
            case 3:
              q->alpha = ScaleLongToQuantum((unsigned int) *pixels);
              break;
          }
          pixels++;
        }
        break;
      }
      default: {
        for (i=0; i < (ssize_t) channels; i++) {
          switch (i) {
            case 0:
              q->red = ScaleCharToQuantum((unsigned char) *pixels);
              break;
            case 1:
              q->green = ScaleCharToQuantum((unsigned char) *pixels);
              break;
            case 2:
              q->blue = ScaleCharToQuantum((unsigned char) *pixels);
              break;
            case 3:
              q->alpha = ScaleCharToQuantum((unsigned char) *pixels);
              break;
          }
          pixels++;
        }
        break;
      }
    }
    q++;
  }
  return MagickTrue;
}

MagickBooleanType ReadChannelPixels(Image *image, size_t channels, size_t row, ssize_t type, const unsigned char *pixels, ExceptionInfo *exception)
{
    register PixelInt
        *magick_restrict pixel;

    register ssize_t
        i;

    register unsigned char
        *magick_restrict q;

    ssize_t
        channel,
        depth;

    MagickBooleanType
        status;

    depth=image->depth;
    status=MagickTrue;
    pixel=(PixelInt *) (image->pixels);
    q=(unsigned char *) pixels;
    switch (type)
    {
        case 0:
        {
            for (i=0; i < (ssize_t) image->columns; i++)
            {
                for (channel=0; channel < (ssize_t) channels; channel++)
                {
                    *pixel++ = ScaleCharToQuantum(*q++);
                }
            }
            break;
        }
        default:
        {
            for (i=0; i < (ssize_t) image->columns; i++)
            {
                for (channel=0; channel < (ssize_t) channels; channel++)
                {
                    *pixel++ = ScaleCharToQuantum(*q++);
                }
            }
            break;
        }
    }
    if (image->alpha_trait != UndefinedPixelTrait)
    {
        register ssize_t
            alpha_channel;

        alpha_channel=channels;
        for (i=0; i < (ssize_t) image->columns; i++)
        {
            if ((i % image->columns) < image->columns)
            {
                switch (image->alpha_trait)
                {
                    case BlendPixelTrait:
                    case OpacityPixelTrait:
                    {
                        *pixel++ = ScaleCharToQuantum(*q++);
                        break;
                    }
                    default:
                    {
                        *pixel++ = ScaleCharToQuantum(*q++);
                        break;
                    }
                }
            }
        }
    }
    return(status);
}

MagickBooleanType ReadPSDPixels(Image *image, size_t channels, size_t row, ssize_t type, const unsigned char *pixels, ExceptionInfo *exception) {
    register PixelInt *p;
    register ssize_t
        y;

    p = GetPixelCache(image, 0, row, image->columns, 1, &image->exception);
    if (p == (PixelInt *) NULL)
        return MagickFalse;

    for (y = 0; y < (ssize_t) image->columns; y++) {
        register ssize_t
            i;

        for (i = 0; i < (ssize_t) channels; i++) {
            switch (type) {
                case 0:
                    *p++ = (PixelInt) *pixels++;
                    break;
                case 1:
                    *p++ = ScaleCharToQuantum((unsigned char) *pixels++);
                    break;
                case 2:
                    *p++ = ScaleShortToQuantum((unsigned short) *pixels++);
                    *p++ = ScaleShortToQuantum((unsigned short) *pixels++);
                    break;
                default:
                    break;
            }
        }
    }

    if (channels > GetPixelChannels(image)) {
        register ssize_t
            i;

        for (i = (ssize_t) GetPixelChannels(image); i < (ssize_t) channels; i++) {
            switch (type) {
                case 0:
                    *p++ = (PixelInt) *pixels++;
                    break;
                case 1:
                    *p++ = ScaleCharToQuantum((unsigned char) *pixels++);
                    break;
                default:
                    break;
            }
        }
    }

    SyncPixelCache(image, &image->exception);
    return MagickTrue;
}

MagickBooleanType ReadPSDPixels(Image *image, size_t channels, size_t row, ssize_t type, const unsigned char *pixels, ExceptionInfo *exception) {
    register PixelInt
        *p;

    register ssize_t
        i;

    size_t
        depth,
        packet_size;

    ssize_t
        alpha;

    alpha = -1;
    packet_size = 4;
    depth = 8;

    p = AcquireAuthenticPixels(image, 0, row, image->columns, 1, exception);
    if (p == (PixelInt *) NULL)
        return MagickFalse;

    for (i = 0; i < (ssize_t) image->columns; i++)
    {
        for (size_t channel = 0; channel < channels; channel++)
        {
            if (type == 0)
            {
                switch (channel)
                {
                    case 0:
                        p[0] = ScaleCharToQuantum(pixels[i * packet_size + 0]);
                        break;
                    case 1:
                        p[1] = ScaleCharToQuantum(pixels[i * packet_size + 1]);
                        break;
                    case 2:
                        p[2] = ScaleCharToQuantum(pixels[i * packet_size + 2]);
                        break;
                    case 3:
                        alpha = 3;
                        p[3] = ScaleCharToQuantum(pixels[i * packet_size + 3]);
                        break;
                    default:
                        break;
                }
            }
            else
            {
                // Additional type handling logic can be added here
            }
            p += 4;
        }
    }

    if (!SyncAuthenticPixels(image, exception))
        return MagickFalse;

    return MagickTrue;
}

